window.JDN = window.JDN || {};
(function (JDN, DATA) {
  const cache = new Map();
  function keyFromPath(path) {
    return String(path || '')
      .split('?')[0]
      .split('#')[0]
      .split('/')
      .pop()
      .replace(/\.json$/i, '');
  }
  function clone(value) {
    if (value == null) return value;
    return JSON.parse(JSON.stringify(value));
  }
  function deepLocalize(value, lang) {
    if (Array.isArray(value)) return value.map((item) => deepLocalize(item, lang));
    if (value && typeof value === 'object') {
      if (Object.prototype.hasOwnProperty.call(value, 'id') && Object.prototype.hasOwnProperty.call(value, 'en')) {
        return value[lang] ?? value.id ?? value.en;
      }
      const out = {};
      Object.keys(value).forEach((k) => { out[k] = deepLocalize(value[k], lang); });
      return out;
    }
    return value;
  }
  function normalize(value) {
    if (Array.isArray(value)) return value.map(normalize);
    if (value && typeof value === 'object') {
      const out = {};
      Object.keys(value).forEach((k) => { out[k] = normalize(value[k]); });
      return out;
    }
    if (typeof value === 'string' && value.startsWith('/assets/')) return JDN.url(value);
    return value;
  }
  JDN.data = function (path, lang) {
    const rawKey = keyFromPath(path);
    const baseKey = rawKey.replace(/-(id|en)$/i, '');
    const raw = DATA[rawKey] ?? DATA[baseKey];
    if (raw == null) return null;
    const memoKey = rawKey + '::' + (lang || '');
    if (cache.has(memoKey)) return clone(cache.get(memoKey));
    const localized = normalize(lang ? deepLocalize(raw, lang) : clone(raw));
    cache.set(memoKey, localized);
    return clone(localized);
  };
  JDN.url = function (path) {
    const base = document.documentElement.getAttribute('data-base-path') || '.';
    const clean = String(path || '').replace(/^\/+/, '');
    return (base === '.' ? './' : base.replace(/\/$/, '') + '/') + clean;
  };
})(window.JDN, window.JDN_DATA);
